// Real mainnet bodies of the moon.cx CPMM: factory EQCAYGE5-ogaKfvlFb-TO_GYKQsuiVOOLbKSDvAKJ9jkvP5W, its pools,
// LP accounts and LP positions. A few admin, boost and cancel bodies come from older moon.cx CPMM
// generations with the same message layout (the current contracts have not sent them yet).

// Admin messages of the moon.cx CPMM factory; pool creation is covered by TestMemepadGraduationMessages.
func TestCpmmFactoryMessages(t *testing.T) {
	t.Run("CpmmFactoryCollectProtocolFees", func(t *testing.T) {
		// older moon.cx CPMM generation with the same body layout: factory 0:1991743C (code d8611bac, deployed early 2026)
		// tx 919ae55b5e89fd84426f110b4f52aadb2ac19910f659f1afa9050559e971e932
		msg := decodeBody[abiMooncx.CpmmFactoryCollectProtocolFees](t, "b5ee9c7241010101005100009dc492cce900000000000000008014eca3d02b1fdd21d685726ea0dcb5c392689e6ba738f97d964d2033f4ff3852d0032a47353e523012f5d18d23fdc4bacd29f55260236972d0d7d496dbf1394ad422f8dfde83", abiMooncx.MooncxCpmmFactoryCollectProtocolFeesMsgOp, abiMooncx.PrefixCpmmFactoryCollectProtocolFees)
		assert.Equal(t, tlb.Uint64(0), msg.QueryId)
		assert.Equal(t, addr("0:a7651e8158fee90eb42b937506e5ae1c9344f35d39c7cbecb269019fa7f9c296"), msg.Pool)
		assert.Equal(t, addr("0:ca91cd4f948c04bd746348ff712eb34a7d549808da5cb435f525b6fc4e52b508"), msg.Recipient)
	})
	t.Run("CpmmFactoryUpdatePoolWallets", func(t *testing.T) {
		// tx 19702d43496992d627776f6c8fc256cc6a862c6e4de0f5877fc6533a4f50de5c (admin to the current factory)
		msg := decodeBody[abiMooncx.CpmmFactoryUpdatePoolWallets](t, "b5ee9c7241010101005100009e51d80e5e0000000000000000800d016314e8c14437d48017c6a4c165f93774716ef67897ebb9465088dd13671e440065cff629411b9bb090dc670f3347b2721ee84330d6f425ed1f6929e9325b6458d692162f", abiMooncx.MooncxCpmmFactoryUpdatePoolWalletsMsgOp, abiMooncx.PrefixCpmmFactoryUpdatePoolWallets)
		assert.Equal(t, tlb.Uint64(0), msg.QueryId)
		assert.Equal(t, addr("0:680b18a7460a21bea400be35260b2fc9bba38b77b3c4bf5dca328446e89b38f2"), msg.Pool)
		assert.Equal(t, msgAddr(""), msg.XWallet)
		assert.Equal(t, addr("0:65cff629411b9bb090dc670f3347b2721ee84330d6f425ed1f6929e9325b6458"), msg.YWallet)
	})
	t.Run("CpmmFactoryUpgradePool", func(t *testing.T) {
		// older moon.cx CPMM generation with the same body layout: factory 0:1991743C (code d8611bac, deployed early 2026)
		// tx 17f4a155265cdb5312f9d3e914bc00816f208f213d066a4eac02d167e2b9ed64
		msg := decodeBodyWithCell[abiMooncx.CpmmFactoryUpgradePool](t, "", abiMooncx.MooncxCpmmFactoryUpgradePoolMsgOp, abiMooncx.PrefixCpmmFactoryUpgradePool)
		assert.Equal(t, tlb.Uint64(0), msg.QueryId)
		assert.Equal(t, addr("0:43714a7c0abe458bd52e6407d010ff0821281257ce7f38ff3f9d00f9fc23ab2a"), msg.Pool)
		require.True(t, msg.NewCode.Exists)
		assertCellHash(t, "c73828c0ed7d3d33e46dd3befab5e71843118fbdbc009321d15e24c556aa8871", &msg.NewCode.Value)
		assert.False(t, msg.NewData.Exists)
	})
	t.Run("CpmmFactoryUpgrade", func(t *testing.T) {
		// older moon.cx CPMM generation with the same body layout: factory 0:1991743C (code d8611bac, deployed early 2026)
		// tx cf1ba56ddc66a46732f17415f9813482e6c2a71d171365d9a4ccbf311189a2ac
		msg := decodeBodyWithCell[abiMooncx.CpmmFactoryUpgrade](t, "", abiMooncx.MooncxCpmmFactoryUpgradeMsgOp, abiMooncx.PrefixCpmmFactoryUpgrade)
		assert.Equal(t, tlb.Uint64(0), msg.QueryId)
		assert.False(t, msg.NewCode.Exists)
		require.True(t, msg.NewData.Exists)
		assertCellHash(t, "827b8680eee3a18b0664b7f6a527d1387e631e51e9baaed7e930177d89a00366", &msg.NewData.Value)
	})
}

// Deploy and swap messages of moon.cx CPMM pools.
func TestCpmmPoolSwapMessages(t *testing.T) {
	t.Run("CpmmPoolDeploy", func(t *testing.T) {
		// tx b680cebe33d3e372b22c2fc848668736a41c667fdfdc982930cddb8f7c673b95 (factory deploys the graduated pool)
		// lpAccCode / lpPositionCode are the codes of the deployed LP accounts and LP positions
		msg := decodeBody[abiMooncx.CpmmPoolDeploy](t, "", abiMooncx.MooncxCpmmPoolDeployMsgOp, abiMooncx.PrefixCpmmPoolDeploy)
		assert.Equal(t, tlb.Uint64(39163), msg.QueryId)
		assert.Equal(t, tlb.Uint8(30), msg.LpFee)
		assert.Equal(t, tlb.Uint8(10), msg.ProtocolFee)
		assertCellHash(t, "e38209f5f8c3f820463eaba96b5c3d1a9f700b3705eb62655eb4181e42edd06a", &msg.LpAccCode)
		assertCellHash(t, "098a032346351b01d0762ab41ebd915f4a47a58020386ded4344a5c6ca5640b6", &msg.LpPositionCode)
	})
	t.Run("CpmmPoolSwap without next hops", func(t *testing.T) {
		// tx d3f8bef5e18e4533e0604b4bea56386efe8c11e833ac47b7df47afecc6801bde (the pool rejects this swap, see SwapReject below)
		msg := decodeBody[abiMooncx.CpmmPoolSwap](t, "b5ee9c72410101010036000067fa45056b7003999b3eee66003d3b42d801c87442ae89da024249a22989c5337ff3b4a053184e46f5bd983c67e4ca8656f4483d444a9155d9", abiMooncx.MooncxCpmmPoolSwapMsgOp, abiMooncx.PrefixCpmmPoolSwap)
		assert.Equal(t, tlb.Uint64(8071463849232852480), msg.QueryId)
		assert.Equal(t, tlb.Coins(13874221), msg.SwapParams.SwapAmount)
		assert.Equal(t, addr("0:e43a215744ed012124d114c4e299bff9da50298c27237adecc1e33f265432b7a"), msg.SwapParams.Excess)
		assert.Equal(t, tlb.Coins(16874), msg.SwapParams.MinOut)
		assert.False(t, msg.SwapParams.NextFulfill.Exists)
		assert.False(t, msg.SwapParams.NextReject.Exists)
	})
	t.Run("CpmmPoolSwap with a next hop", func(t *testing.T) {
		// tx ba0e0bdb848c540dd1e0b460af227913b9eb4c78445f5d0f2439090757e448e9 (the pool rejects this swap)
		msg := decodeBodyWithCell[abiMooncx.CpmmPoolSwap](t, "b5ee9c72410102010062000273fa45056b0000003400000000513af3da988801fd77c48bbb83a47e2957ba977395a666b9954814f12229a471be6bb30c9393bcc0855807f71ddc01010043801fd77c48bbb83a47e2957ba977395a666b9954814f12229a471be6bb30c9393bd0d002d50f", abiMooncx.MooncxCpmmPoolSwapMsgOp, abiMooncx.PrefixCpmmPoolSwap)
		assert.Equal(t, tlb.Uint64(223338299392), msg.QueryId)
		assert.Equal(t, tlb.Coins(84544432520), msg.SwapParams.SwapAmount)
		assert.Equal(t, addr("0:febbe245ddc1d23f14abdd4bb9cad3335ccaa40a789114d238df35d98649c9de"), msg.SwapParams.Excess)
		assert.Equal(t, tlb.Coins(4581660539118), msg.SwapParams.MinOut)
		require.True(t, msg.SwapParams.NextFulfill.Exists)
		assertCellHash(t, "6e4eac32f3d12fe3ba498ed14ff532055311e945e40a49afb7b21035ea9e9a78", &msg.SwapParams.NextFulfill.Value)
		require.True(t, msg.SwapParams.NextReject.Exists)
		assertCellHash(t, "6e4eac32f3d12fe3ba498ed14ff532055311e945e40a49afb7b21035ea9e9a78", &msg.SwapParams.NextReject.Value)
	})
	t.Run("SwapFulfill", func(t *testing.T) {
		// tx fab4a76d82b63022aa8e8c7428215f81baeb949986ad170649c53bb921c96f29 (GRAM paid to the trader)
		msg := decodeBody[abiMooncx.SwapFulfill](t, "b5ee9c724101010100130000219d1426438dd95e10016d2e6c4ff5e9a3b45510145c", abiMooncx.MooncxSwapFulfillMsgOp, abiMooncx.PrefixSwapFulfill)
		assert.Equal(t, tlb.Uint64(10221304252130471532), msg.QueryId)
		assert.Equal(t, tlb.Coins(4284389947), msg.Amount)
		assert.False(t, msg.Payload.Exists)
	})
	t.Run("SwapFulfill with a next hop payload", func(t *testing.T) {
		// tx cd5126fbeb3fc4ddd22e5bd95380c1786025375fce8c99979c9788510b8752a3 (GRAM paid to the next hop with its payload)
		msg := decodeBodyWithCell[abiMooncx.SwapFulfill](t, "", abiMooncx.MooncxSwapFulfillMsgOp, abiMooncx.PrefixSwapFulfill)
		assert.Equal(t, tlb.Uint64(1792869434419), msg.QueryId)
		assert.Equal(t, tlb.Coins(57138213193), msg.Amount)
		require.True(t, msg.Payload.Exists)
		assertCellHash(t, "a8125fbe47dcf7743b82096e8b22b46d71733a7efc162a49264fe3b12bc9ad96", &msg.Payload.Value)
	})
	t.Run("SwapReject", func(t *testing.T) {
		// tx 2e8a32fbc4fed40eb610c51816fb19b20fbf87ca0bb7a88b4f9b19de694e21a1 (answer to the CpmmPoolSwap without next hops sample)
		msg := decodeBody[abiMooncx.SwapReject](t, "b5ee9c7241010101001200001fff32da997003999b3eee66003d3b42d4afd54eda", abiMooncx.MooncxSwapRejectMsgOp, abiMooncx.PrefixSwapReject)
		assert.Equal(t, tlb.Uint64(8071463849232852480), msg.QueryId)
		assert.Equal(t, tlb.Coins(13874221), msg.Amount)
		assert.False(t, msg.Payload.Exists)
	})
}

// Liquidity messages of moon.cx CPMM pools.
func TestCpmmPoolLiquidityMessages(t *testing.T) {
	t.Run("CpmmPoolDepositLiquidity without split", func(t *testing.T) {
		// tx dd4fb977fef9e1505aabfbe3d760af0db7c053d8eac13936cfd02136aa624112
		msg := decodeBody[abiMooncx.CpmmPoolDepositLiquidity](t, "b5ee9c7241010101001500002590af0b63000001a172faad256013f13784d18270c91974", abiMooncx.MooncxCpmmPoolDepositLiquidityMsgOp, abiMooncx.PrefixCpmmPoolDepositLiquidity)
		assert.Equal(t, tlb.Uint64(1792930393381), msg.QueryId)
		assert.Equal(t, tlb.Coins(1370421218584), msg.MinLpOut)
		assert.False(t, msg.Locked)
		assert.False(t, msg.Split.Exists)
	})
	t.Run("CpmmPoolProvideLiquidity", func(t *testing.T) {
		// tx bafeb87bff22200a7783186b434da64737c600de5029417408e46f038c4f40a7 (LP account sends the amounts of both legs of the deposit above)
		msg := decodeBody[abiMooncx.CpmmPoolProvideLiquidity](t, "b5ee9c7241010101004300008148a936dd000001a172faad25800e646af05fe48a7e40258bf33e4b16b5e944efe45f032063a8ec3f150777687a4a05e394e3a6d10d9316ec000c027e26f09a3040e7aa226d", abiMooncx.MooncxCpmmPoolProvideLiquidityMsgOp, abiMooncx.PrefixCpmmPoolProvideLiquidity)
		assert.Equal(t, tlb.Uint64(1792930393381), msg.QueryId)
		assert.Equal(t, addr("0:73235782ff2453f2012c5f99f258b5af4a277f22f819031d4761f8a83bbb43d2"), msg.Provider)
		assert.Equal(t, tlb.Coins(12646511059), msg.XAmount)
		assert.Equal(t, tlb.Coins(150000000000000), msg.YAmount)
		assert.Equal(t, tlb.Coins(1370421218584), msg.MinLpOut)
		assert.False(t, msg.Locked)
		assert.False(t, msg.Split.Exists)
	})
	t.Run("CpmmPoolProvideLiquidity with split", func(t *testing.T) {
		// tx 4a1d5ff0c7bce568510b0844b883a7b7f14630dbd356e4a7b940d294c332a89c (graduation of the memepad curve, locked LP split 70/30)
		msg := decodeBody[abiMooncx.CpmmPoolProvideLiquidity](t, "", abiMooncx.MooncxCpmmPoolProvideLiquidityMsgOp, abiMooncx.PrefixCpmmPoolProvideLiquidity)
		assert.Equal(t, tlb.Uint64(39163), msg.QueryId)
		assert.Equal(t, addr("0:b0e8286b645919ab2b4fd3b1fa87555d84b2d4b07908d64a8d4cc8a741ac66a2"), msg.Provider)
		assert.Equal(t, tlb.Coins(1998835779277), msg.XAmount)
		assert.Equal(t, tlb.Coins(200000000000000000), msg.YAmount)
		assert.Equal(t, tlb.Coins(0), msg.MinLpOut)
		assert.True(t, msg.Locked)
		require.True(t, msg.Split.Exists)
		require.NotNil(t, msg.Split.Value.Value)
		assert.Equal(t, addr("0:df36ec602af55dc78c2f2ffeac2e0fb3c01318967b51384367a7acd1a7382a22"), msg.Split.Value.Value.ARecipient)
		assert.Equal(t, tlb.Uint16(7000), msg.Split.Value.Value.ABps)
		assert.Equal(t, addr("0:24606bd29c7a1546e7c66e6e04335adeac90f0af9773e05f217d3012b14309f1"), msg.Split.Value.Value.BRecipient)
	})
	t.Run("CpmmPoolWithdrawLiquidity", func(t *testing.T) {
		// tx 126f782799a2e8c5e65deb87c32e9253c4d2635be1b1f2ed9862d6e0d8273182 (sent by an LP position)
		msg := decodeBody[abiMooncx.CpmmPoolWithdrawLiquidity](t, "b5ee9c724101010100750000e5cbd7f377000001a172301ac6801e75622c6cff00d544703598d45d23069f237696f969d44c34ed42dd33960d7eab8f8400aae2000000000000000000000000000000000006e2f1f977f2f55d8741df9fbea0460000000000000000000000000000000482c4dd9bbd3738280df57f99ed73db7b6d43ecc6", abiMooncx.MooncxCpmmPoolWithdrawLiquidityMsgOp, abiMooncx.PrefixCpmmPoolWithdrawLiquidity)
		assert.Equal(t, tlb.Uint64(1792917117638), msg.QueryId)
		assert.Equal(t, addr("0:f3ab116367f806aa2381acc6a2e91834f91bb4b7cb4ea261a76a16e99cb06bf5"), msg.Provider)
		assert.Equal(t, tlb.Coins(857953293681), msg.LpPos)
		assertUint256(t, "17878388457788568960999197098594339", msg.XFeesPos)
		assertUint256(t, "767475646035756381622016510409437736381", msg.YFeesPos)
	})
	t.Run("CpmmPoolWithdrawFees", func(t *testing.T) {
		// tx 00eaed2bdcdf7214a4c121579c77f7977119f763a0da7a7e5e0c63ab52a6ff40 (sent by an LP position)
		msg := decodeBody[abiMooncx.CpmmPoolWithdrawFees](t, "b5ee9c724101010100770000e9d5c9f8c300000000000099c5801be6dd8c055eabb8f185e5ffd585c1f678026312cf6a27086cf4f59a34e705444e032511073a74fc000000000000000000000000000000000005dfbb80dc05a674555c154c89a6fa0000000000000000000000000000000328b4ffd10d3aba05aff357033c87a1cfed5c0c05", abiMooncx.MooncxCpmmPoolWithdrawFeesMsgOp, abiMooncx.PrefixCpmmPoolWithdrawFees)
		assert.Equal(t, tlb.Uint64(39365), msg.QueryId)
		assert.Equal(t, addr("0:df36ec602af55dc78c2f2ffeac2e0fb3c01318967b51384367a7acd1a7382a22"), msg.Provider)
		assert.Equal(t, tlb.Coins(442589998037630), msg.LpPos)
		assertUint256(t, "15249658590375123950174019294385021", msg.XFeesPos)
		assertUint256(t, "537478011302988746113454749600522162407", msg.YFeesPos)
	})
	t.Run("CpmmPoolCancelDeposit", func(t *testing.T) {
		// older moon.cx CPMM generation with the same body layout: Aug 2026, LpAccount code aa5eaa9a
		// tx f570f6c94b6e2e4c4d03f92b0b91c0b7582e010f47e32352a4b59732e1bc59eb (sent by an LP account)
		msg := decodeBody[abiMooncx.CpmmPoolCancelDeposit](t, "b5ee9c724101010100360000671f911dd9000001a038f4fb70800ff01bf0f1422e5ebb410b39df1b631f720f7bcbb7e367b22d025c4afb90de5dca4841b499001098218f4c", abiMooncx.MooncxCpmmPoolCancelDepositMsgOp, abiMooncx.PrefixCpmmPoolCancelDeposit)
		assert.Equal(t, tlb.Uint64(1787661974384), msg.QueryId)
		assert.Equal(t, addr("0:7f80df878a1172f5da0859cef8db18fb907bde5dbf1b3d916812e257dc86f2ee"), msg.Provider)
		assert.Equal(t, tlb.Coins(155170000000), msg.XAmount)
		assert.Equal(t, tlb.Coins(0), msg.YAmount)
	})
	t.Run("CpmmPoolBoost", func(t *testing.T) {
		// older moon.cx CPMM generation with the same body layout: pool (code c73828c0/3b5fc603/94a17dd0)
		// tx 69d29923ba4bb5a4cbf56718827d8463601b6ac681fedc9a2f0f22a61e1679b0
		msg := decodeBody[abiMooncx.CpmmPoolBoost](t, "b5ee9c7241010101000e00001850bbec040000000000000309d426a52e", abiMooncx.MooncxCpmmPoolBoostMsgOp, abiMooncx.PrefixCpmmPoolBoost)
		assert.Equal(t, tlb.Uint64(777), msg.QueryId)
	})
}

