// Get methods of moon.cx CPMM LP positions, decoded from real mainnet results.
func TestCpmmPositionGetMethods(t *testing.T) {
	t.Run("getPosition", func(t *testing.T) {
		// TON Center runGetMethod on the LP position EQAd-V1KnqmB8waLUle8K2F3_-aM_hHihVqH5_0RQXtPbiUj
		const stack = ""
		st := cellStack(stack)
		res, err := abiMooncx.DecodeGetPosition(&st)
		require.NoError(t, err)
		require.NotNil(t, res.Value)
		assert.Equal(t, addr("0:4bc147805689dc8669bba66e8f221562c6b82eb95e26461aa576be7d1fb57d45"), res.Value.Pool)
		assert.Equal(t, addr("0:7f80df878a1172f5da0859cef8db18fb907bde5dbf1b3d916812e257dc86f2ee"), res.Value.User)
		require.NotNil(t, res.Value.Data.Value)
		assert.Equal(t, tlb.Coins(712914381543953), res.Value.Data.Value.Lp)
		assertUint256(t, "17026258206555290003436729253770969", res.Value.Data.Value.XFeesLp)
		assertUint256(t, "932450856210301610258258671618200264467", res.Value.Data.Value.YFeesLp)
		assert.False(t, res.Value.Frozen)
		assert.True(t, res.Value.Locked)
		assert.Equal(t, res, decodeGetter(t, "getPosition", cellStack(stack), "GetPosition_MooncxCpmmPositionResult"))
		locked := intStack(-1) // getLocked on the same position
		ok, err := abiMooncx.DecodeGetLocked(&locked)
		require.NoError(t, err)
		assert.True(t, ok)
		assert.Equal(t, true, decodeGetter(t, "getLocked", intStack(-1), "GetLocked_MooncxCpmmPositionResult"))
	})
	t.Run("getPosition of another position", func(t *testing.T) {
		// TON Center runGetMethod on the LP position 0:3094FB7BD05C0E65F75E89E8B50D679935F90611E5496FD5630FC7C0EFC40A5D
		const stack = ""
		st := cellStack(stack)
		res, err := abiMooncx.DecodeGetPosition(&st)
		require.NoError(t, err)
		require.NotNil(t, res.Value)
		assert.Equal(t, addr("0:ef8c5eab6ffd33874c501755e1bfb3040cd5cde65fd8e86f064b0066b3c1229d"), res.Value.Pool)
		assert.Equal(t, addr("0:24606bd29c7a1546e7c66e6e04335adeac90f0af9773e05f217d3012b14309f1"), res.Value.User)
		require.NotNil(t, res.Value.Data.Value)
		assert.Equal(t, tlb.Coins(42144128878922), res.Value.Data.Value.Lp)
		assertUint256(t, "0", res.Value.Data.Value.XFeesLp)
		assertUint256(t, "0", res.Value.Data.Value.YFeesLp)
		assert.False(t, res.Value.Frozen)
		assert.True(t, res.Value.Locked)
		assert.Equal(t, res, decodeGetter(t, "getPosition", cellStack(stack), "GetPosition_MooncxCpmmPositionResult"))
	})
	t.Run("getPosition of a CLMM LP position is not a CPMM position", func(t *testing.T) {
		// TON Center runGetMethod on the CLMM LP position 0:e08ca91b5badee0880dec70b6d115cd17b67a02964e5c188e35831e818a9c526
		st := cellStack("")
		_, err := abiMooncx.DecodeGetPosition(&st)
		assert.Error(t, err)
	})
}

// decodePayload decodes a jetton forward payload cell with the generated type T,
// checks that the cell is fully consumed and encodes back to the same cell, and
// that the abi jetton payload decoder resolves it to the expected operation.
func decodePayload[T interface{ ToCell() (*boc.Cell, error) }, PT interface {
	*T
	tlb.UnmarshalerTLB
}](t *testing.T, bocHex string, opName abi.JettonOpName, opCode uint64) T {
	t.Helper()
	want, err := boc.MustDeserializeSinglRootHex(bocHex).Hash256()
	require.NoError(t, err)

	cell := boc.MustDeserializeSinglRootHex(bocHex)
	var p T
	require.NoError(t, PT(&p).UnmarshalTLB(cell, tlb.NewDecoder()))
	assert.Zero(t, cell.BitsAvailableForRead(), "leftover bits")
	assert.Zero(t, cell.RefsAvailableForRead(), "leftover refs")
	assertEncodesTo(t, want, p)

	var payload abi.JettonPayload
	require.NoError(t, payload.UnmarshalTLB(boc.MustDeserializeSinglRootHex(bocHex), tlb.NewDecoder()))
	assert.Equal(t, opName, payload.SumType)
	require.NotNil(t, payload.OpCode)
	assert.Equal(t, uint32(opCode), *payload.OpCode)
	decoded, ok := payload.Value.(T)
	require.True(t, ok, "jetton payload decoder returned %T", payload.Value)
	assertEncodesTo(t, want, decoded)
	return p
}

// decodeBodyWithCell is decodeBody for a body that carries a non-null cell?
// field. The generated decoder reads such a field as Maybe ^Cell, as the
// contracts write it, but tongo's generated encoder replaces the whole cell when
// it writes a non-null cell? field, so the encode-back check of decodeBody is
// replaced by comparing both decoded values.
func decodeBodyWithCell[T any, PT interface {
	*T
	tlb.UnmarshalerTLB
}](t *testing.T, bocHex string, opName abi.MsgOpName, opCode uint64) T {
	t.Helper()
	cell := boc.MustDeserializeSinglRootHex(bocHex)
	var msg T
	require.NoError(t, PT(&msg).UnmarshalTLB(cell, tlb.NewDecoder()))
	assert.Zero(t, cell.BitsAvailableForRead(), "leftover bits")
	assert.Zero(t, cell.RefsAvailableForRead(), "leftover refs")

	gotOpCode, gotOpName, value, err := abi.InternalMessageDecoder(boc.MustDeserializeSinglRootHex(bocHex), nil)
	require.NoError(t, err)
	require.NotNil(t, gotOpCode)
	require.NotNil(t, gotOpName)
	assert.Equal(t, uint32(opCode), *gotOpCode)
	assert.Equal(t, opName, *gotOpName)
	decoded, ok := value.(*T)
	require.True(t, ok, "abi decoder returned %T", value)
	assert.Equal(t, msg, *decoded)
	return msg
}

// decodePayloadWithCell is decodePayload for a payload with a non-null cell?
// field (see decodeBodyWithCell).
func decodePayloadWithCell[T any, PT interface {
	*T
	tlb.UnmarshalerTLB
}](t *testing.T, bocHex string, opName abi.JettonOpName, opCode uint64) T {
	t.Helper()
	cell := boc.MustDeserializeSinglRootHex(bocHex)
	var p T
	require.NoError(t, PT(&p).UnmarshalTLB(cell, tlb.NewDecoder()))
	assert.Zero(t, cell.BitsAvailableForRead(), "leftover bits")
	assert.Zero(t, cell.RefsAvailableForRead(), "leftover refs")

	var payload abi.JettonPayload
	require.NoError(t, payload.UnmarshalTLB(boc.MustDeserializeSinglRootHex(bocHex), tlb.NewDecoder()))
	assert.Equal(t, opName, payload.SumType)
	require.NotNil(t, payload.OpCode)
	assert.Equal(t, uint32(opCode), *payload.OpCode)
	decoded, ok := payload.Value.(T)
	require.True(t, ok, "jetton payload decoder returned %T", payload.Value)
	assert.Equal(t, p, decoded)
	return p
}

// decodeNotificationPayload decodes a transfer_notification body with the abi
// decoder and returns its forward payload, which must be a ref decoded as T.
func decodeNotificationPayload[T any](t *testing.T, bocHex string, opName abi.JettonOpName) T {
	t.Helper()
	_, gotOpName, value, err := abi.InternalMessageDecoder(boc.MustDeserializeSinglRootHex(bocHex), nil)
	require.NoError(t, err)
	require.NotNil(t, gotOpName)
	require.Equal(t, abi.JettonNotifyMsgOp, *gotOpName)
	body, ok := value.(abi.JettonNotifyMsgBody)
	require.True(t, ok, "abi decoder returned %T", value)
	return forwardPayload[T](t, body.ForwardPayload, opName)
}

// decodeTransferPayload does the same for a jetton_transfer body.
func decodeTransferPayload[T any](t *testing.T, bocHex string, opName abi.JettonOpName) T {
	t.Helper()
	_, gotOpName, value, err := abi.InternalMessageDecoder(boc.MustDeserializeSinglRootHex(bocHex), nil)
	require.NoError(t, err)
	require.NotNil(t, gotOpName)
	require.Equal(t, abi.JettonTransferMsgOp, *gotOpName)
	body, ok := value.(abi.JettonTransferMsgBody)
	require.True(t, ok, "abi decoder returned %T", value)
	return forwardPayload[T](t, body.ForwardPayload, opName)
}

func forwardPayload[T any](t *testing.T, fp tlb.EitherRef[abi.JettonPayload], opName abi.JettonOpName) T {
	t.Helper()
	assert.True(t, fp.IsRight, "forward payload must be a ref")
	require.Equal(t, opName, fp.Value.SumType)
	p, ok := fp.Value.Value.(T)
	require.True(t, ok, "forward payload decoded as %T", fp.Value.Value)
	return p
}

func assertUint256(t *testing.T, want string, got tlb.Uint256) {
	t.Helper()
	v := big.Int(got)
	assert.Equal(t, want, v.String())
}

// assertKeys checks the number of bins of a map and its smallest and largest bin.
func assertKeys(t *testing.T, keys []tlb.Int64, n int, first, last int64) {
	t.Helper()
	require.Len(t, keys, n)
	sorted := slices.Clone(keys)
	slices.Sort(sorted)
	assert.Equal(t, tlb.Int64(first), sorted[0])
	assert.Equal(t, tlb.Int64(last), sorted[len(sorted)-1])
}

func mapValue[T any](t *testing.T, m tlb.HashmapE[tlb.Int64, T], bin int64) T {
	t.Helper()
	v, ok := m.Get(tlb.Int64(bin))
	require.True(t, ok, "no bin %d", bin)
	return v
}

func rangeAddr(t *testing.T, m tlb.Hashmap[tlb.Int16, tlb.InternalAddress], rangeNum int16) tlb.InternalAddress {
	t.Helper()
	v, ok := m.Get(tlb.Int16(rangeNum))
	require.True(t, ok, "no range %d", rangeNum)
	return v
}

// cellStack is the stack of a get method that returns one cell.
func cellStack(bocHex string) tlb.VmStack {
	var st tlb.VmStack
	st.Put(tlb.VmStackValue{SumType: "VmStkCell", VmStkCell: tlb.Ref[boc.Cell]{Value: *boc.MustDeserializeSinglRootHex(bocHex)}})
	return st
}

func intStack(v int64) tlb.VmStack {
	var st tlb.VmStack
	st.Put(tlb.VmStackValue{SumType: "VmStkTinyInt", VmStkTinyInt: v})
	return st
}

// decodeGetter runs the decoders abi registers for a get method (the ones the
// contract inspector uses) and returns the result carrying the wanted type hint.
func decodeGetter(t *testing.T, method string, stack tlb.VmStack, hint string) any {
	t.Helper()
	for _, decode := range abi.KnownGetMethodsDecoder[method] {
		gotHint, value, err := decode(stack)
		if err == nil && gotHint == hint {
			return value
		}
	}
	t.Fatalf("no %s decoder returned %s", method, hint)
	return nil
}
